/**
 * SQAF — Secret redaction (Stage 5 security adjustment). See ADR-0008 D9.
 *
 * Pure text helpers shared by the error layer (SqafError messages and
 * chained causes) and the fixtures (Playwright errors of tests that handle
 * credentials). They complement, never replace, the rule that secrets are not
 * written anywhere in the first place.
 */

export const REDACTED = '[REDACTED]';

/**
 * Every password generated by SQAF: `Sqaf#` + 16 base64url characters (12 random
 * bytes). The pattern also covers LONGER values with the same prefix, such as
 * the frozen Stage 0 baseline password (`Sqaf#` + a UUID), so a value is never
 * redacted only in part.
 */
export const GENERATED_PASSWORD_PREFIX = 'Sqaf#';
const GENERATED_PASSWORD_SOURCE = 'Sqaf#[A-Za-z0-9_-]{16,}';

/**
 * Values typed by Playwright actions, as they appear in a call log
 * (`- fill("…")`, `type("…")`, `pressSequentially("…")`, `insertText("…")`)
 * or in a step title (`Fill "…"`, `Type "…"`, `Press sequentially "…"`).
 * Playwright prints them when an action fails after resolving its element.
 */
const TYPED_CALL = /\b(fill|type|pressSequentially|insertText)\((["'`])((?:\\.|(?!\2)[^\\])*)\2/g;
const TYPED_TITLE = /\b(Fill|Type|Press sequentially|Insert text) "((?:\\.|[^"\\])*)"/g;

/** Replaces every value typed by a Playwright action (call log or step title). */
export function redactTypedValues(text: string): string {
  return text
    .replace(TYPED_CALL, (_m, action: string, quote: string) => `${action}(${quote}${REDACTED}${quote}`)
    .replace(TYPED_TITLE, (_m, action: string) => `${action} "${REDACTED}"`);
}

/** Keys whose value is a secret (case-insensitive). */
export const SECRET_KEY = /pass(?:word|wd)?|secret|token|credential|authorization|cookie/i;

/** Secret-looking key names inside a text. */
const KEY = '[A-Za-z_-]*(?:password|passwd|pass|pwd|secret|token|credentials?)';

/**
 * Secret pairs as they appear in machine formats (prose such as
 * "$.password: missing required field" is NOT touched):
 *  - form bodies and query strings: `password=value`
 *  - JSON: `"password": "value"`
 *  - headers: `Authorization: …` and `Cookie: …` (rest of the line)
 */
const FORM_PAIR = new RegExp(String.raw`\b(${KEY})=([^\s"'&,;}\]]+)`, 'gi');
const JSON_PAIR = new RegExp(String.raw`("${KEY}"\s*:\s*")((?:[^"\\]|\\.)*)(")`, 'gi');
const HEADER_PAIR = /\b((?:proxy-)?authorization|(?:set-)?cookie)(\s*[:=]\s*)([^\r\n]+)/gi;

/** A new matcher of generated passwords (a fresh RegExp: global regexes are stateful). */
export function generatedPasswordPattern(): RegExp {
  return new RegExp(GENERATED_PASSWORD_SOURCE, 'g');
}

/** Replaces secret pairs (form, JSON, headers) and SQAF-generated passwords in a text. */
export function redactSecrets(text: string): string {
  return text
    .replace(generatedPasswordPattern(), REDACTED)
    .replace(FORM_PAIR, (_m, key: string) => `${key}=${REDACTED}`)
    .replace(JSON_PAIR, (_m, head: string, _value: string, tail: string) => `${head}${REDACTED}${tail}`)
    .replace(HEADER_PAIR, (_m, key: string, separator: string) => `${key}${separator}${REDACTED}`);
}

/** Replaces every occurrence of the given exact values (for secrets known at runtime). */
export function redactValues(text: string, secrets: readonly string[]): string {
  let out = text;
  for (const secret of secrets) {
    if (secret.length > 0) out = out.split(secret).join(REDACTED);
  }
  return out;
}
